import 'dart:convert';

void main() {
  String jsonText = '''
  [
    {"name": "Phone", "price": 500},
    {"name": "Laptop", "price": 1200},
    {"name": "Mouse", "price": 25}
  ]
  ''';

  List<dynamic> products = jsonDecode(jsonText);

  var mostExpensive = products[0];
