import 'dart:convert';

class Book {
  String title;
  double price;
  Book(this.title, this.price);

  factory Book.fromJson(Map<String, dynamic> json) {
    return Book(json['title'], (json['price'] as num).toDouble());
  }

  Map<String, dynamic> toJson() {
    return {'title': title, 'price': price};
  }
}

void main() {
  var json = jsonDecode('{"title": "Dart Basics", "price": 50}');
  Book b = Book.fromJson(json);
  b.price = 60;
  print(jsonEncode(b.toJson()));
  // {"title":"Dart Basics","price":60.0}
}
